import { stdout } from std.io;
contract Point { x: Int32; y: Int32; }
enum Shape {
    Circle(r: Int32),
    Square(s: Int32)
}
class Holder {
    p: Point;
    construct(p: Point) { this.p = p; }
}
fn area(s: Shape): Int32 {
    return match s {
        Shape.Circle(r) => r * r * 3,
        Shape.Square(w) => w * w
    };
}
fn main(): Void {
    inmut h = Holder({ x: 1, y: 2 });
    stdout.println(h.p.x + h.p.y);
    stdout.println(area(Shape.Circle(2)));
    stdout.println(area(Shape.Square(3)));
    inmut a: Object = { x: 1, y: 2 };
    inmut b: Object = { x: 1, y: 2 };
    stdout.println(a is b);
}
